{
  "hero": {
    "heading": "Plan trips together, stress-free.",
    "subheading": "Wander brings your crew into one place — vote on destinations, split expenses, sync calendars, and let AI handle the heavy lifting.",
    "ctaPrimary": "Start a Trip",
    "ctaSecondary": "See how it works"
  },
  "tripTypes": {
    "heading": "What kind of adventure are you planning?",
    "local": {
      "title": "Local Adventure",
      "description": "Discover hidden gems in your city or nearby. Perfect for weekend getaways and day trips with friends.",
      "badge": "No passport needed"
    },
    "overseas": {
      "title": "Overseas Escape",
      "description": "Plan your dream international trip with everything from flights to local experiences, all in one place.",
      "badge": "Passport ready"
    }
  },
  "features": {
    "heading": "Everything your group needs to plan the perfect trip",
    "subheading": "From the first idea to the final recap — Wandertogether has every tool your crew needs.",
    "items": [
      {
        "id": "feat-1",
        "title": "Collaborative Planning",
        "description": "Invite your whole crew and plan together in real time. Everyone has a voice.",
        "size": "large"
      },
      {
        "id": "feat-2",
        "title": "Polls & Voting",
        "description": "Create polls for destinations, activities, or restaurants. Set a time limit and let the votes roll in.",
        "size": "small"
      },
      {
        "id": "feat-3",
        "title": "Expense Tracker",
        "description": "Track every cost and see exactly what each person owes. Filter by food, flights, hotels, and more.",
        "size": "small"
      },
      {
        "id": "feat-4",
        "title": "AI Trip Assistant",
        "description": "Get smart suggestions to save time and money. Flag weather issues, events, and trip blockers before they happen.",
        "size": "small"
      },
      {
        "id": "feat-5",
        "title": "Calendar Availability",
        "description": "Find the best dates for everyone with a When2Meet-style availability grid.",
        "size": "small"
      },
      {
        "id": "feat-6",
        "title": "Trip Memories",
        "description": "Upload photos and videos during your trip. Get a beautiful post-trip recap when you're back home.",
        "size": "small"
      }
    ]
  },
  "howItWorks": {
    "heading": "Planning a trip has never been this easy",
    "steps": [
      {
        "id": "step-1",
        "number": "01",
        "title": "Create your trip",
        "description": "Choose local or overseas, set your dates, and give your adventure a name."
      },
      {
        "id": "step-2",
        "number": "02",
        "title": "Invite your crew",
        "description": "Send invites to friends and family. Everyone joins in seconds."
      },
      {
        "id": "step-3",
        "number": "03",
        "title": "Plan together",
        "description": "Vote on places, split costs, sync calendars, and let AI optimize the rest."
      }
    ]
  },
  "cta": {
    "heading": "Your next adventure is one invite away.",
    "subheading": "Join thousands of groups already planning their dream trips on Wandertogether.",
    "button": "Start Planning for Free"
  }
}
